using System.Text.Json;
using System.Text.RegularExpressions;
namespace LocalChat;
sealed class BrowserElement {public int Index {get;set;}public string Tag {get;set;}="";public string Type {get;set;}="";public string Label {get;set;}="";public string Name {get;set;}="";public string Autocomplete {get;set;}="";public bool Disabled {get;set;}}
sealed class BrowserSnapshot {public string Url {get;set;}="";public string Title {get;set;}="";public string Text {get;set;}="";public int IframeCount {get;set;}public List<BrowserElement> Elements {get;set;}=new();public override string ToString()=>"URL: "+Url+"\n"+Title+"\n"+Text[..Math.Min(Text.Length,1200)]+"\nЭЛЕМЕНТЫ (index; роль; имя; disabled):\n"+string.Join("\n",Elements.Take(60).Select(e=>$"{e.Index}; {e.Tag}/{e.Type}; {e.Label[..Math.Min(e.Label.Length,90)]}; {e.Disabled}"))+"\nIframe: "+IframeCount+" (внутреннее содержимое iframe не извлечено). Значения полей не читаются.";}
static class BrowserAutomation {
 public static bool Sensitive(BrowserElement e)=>Regex.IsMatch(e.Type+" "+e.Autocomplete+" "+e.Name+" "+e.Label,@"password|парол|one.time|(?:^|\W)otp(?:\W|$)|верификац|код подтверж|sms.code|cc-number|cc-csc|cc-exp|credit.card|card.number|cvv|cvc|security.code|(?:^|\W)(?:token|secret)(?:\W|$)",RegexOptions.IgnoreCase);
 public static void Validate(BrowserElement e,string? text){if(e.Disabled||Sensitive(e)||e.Type is "file" or "hidden")throw new Exception("Пароли, коды, платёжные, файловые и недоступные поля — только вручную.");if(text!=null&&(text.Length>2000||e.Tag is not ("input" or "textarea" or "contenteditable")||e.Type is not ("" or "text" or "search" or "email" or "tel" or "url" or "number" or "textarea")))throw new Exception("Текст можно вводить только в обычное текстовое поле, до 2000 символов.");}
 public static string Script(string key,string? text){string k=JsonSerializer.Serialize("[data-nora-target=\""+key+"\"]"),v=JsonSerializer.Serialize(text);return """
(()=>{const list=document.querySelectorAll(__SELECTOR__);if(list.length!==1)throw Error('Элемент изменился: обнови browser_snapshot');const e=list[0],r=e.getBoundingClientRect();if(!r.width||!r.height||e.disabled||e.readOnly||e.getAttribute('aria-disabled')==='true')throw Error('Элемент недоступен');const meta=[e.type,e.name,e.autocomplete,e.getAttribute('aria-label'),e.labels?.[0]?.innerText,e.placeholder].join(' ');if(/password|парол|one.time|верификац|sms.code|\botp\b|код подтверж|cc-number|cc-csc|cc-exp|credit.card|card.number|cvv|cvc|security.code|\btoken\b|\bsecret\b/i.test(meta)||e.type==='file'||e.type==='hidden')throw Error('Защищённое поле: только вручную');e.scrollIntoView({block:'nearest',inline:'nearest'});const p=e.getBoundingClientRect(),at=document.elementFromPoint(p.left+p.width/2,p.top+p.height/2);if(at&&at!==e&&!e.contains(at))throw Error('Элемент перекрыт; обнови browser_snapshot');const value=__VALUE__;if(value!==null){if(e.isContentEditable){e.focus();const range=document.createRange();range.selectNodeContents(e);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);if(!document.execCommand('insertText',false,value)){e.textContent=value;e.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'insertText',data:value}));}e.dispatchEvent(new Event('change',{bubbles:true}));}else{if(!['INPUT','TEXTAREA'].includes(e.tagName)||!['text','search','email','tel','url','number','textarea'].includes(e.type))throw Error('Поле не текстовое');const proto=e.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype;Object.getOwnPropertyDescriptor(proto,'value').set.call(e,value);e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}));}}else{e.click();}return {ok:true};})()
""".Replace("__SELECTOR__",k).Replace("__VALUE__",v);}
}
